package os.aios.agent;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;
/** Real model + production history composer acceptance, on a dedicated test conversation. */
public final class HistoryDragUiTests extends Instrumentation {
 int initialY,finalY;boolean initialFollow,finalFollow;ScrollView viewport;String thread;Activity activity;int checks;long sent;boolean sawPartial;String prompt="这是 AIOS 历史流式验收，不调用工具，不保存记忆。请连续输出 45 行不同的简短测试句，每行带序号，最后一行写 STREAM_END_45。不要省略。请使用当前系统首选语言。";
 public void onCreate(Bundle p){super.onCreate(p);thread=p.getString("thread");start();}
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}
 EditText input(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){EditText e=input(g.getChildAt(i));if(e!=null)return e;}}return null;}
 View described(View v,String label){if(label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View found=described(g.getChildAt(i),label);if(found!=null)return found;}}return null;}
 String text(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText()).append('\n');if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)s.append(text(g.getChildAt(i)));}return s.toString();}
 void screenshot(String name)throws Exception{android.graphics.Bitmap b=getUiAutomation().takeScreenshot();if(b!=null){File dir=new File(getTargetContext().getFilesDir(),"dynamic-acceptance");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();}}
 public void onStart(){Bundle out=new Bundle();try{
  Context c=getTargetContext();check(thread!=null&&!thread.isEmpty(),"dedicated existing test thread supplied");
  activity=startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("workspace_tab","sessions").putExtra("workspace_session","codex:"+thread));
  Thread.sleep(1500);runOnMainSync(()->{EditText field=input(activity.getWindow().getDecorView());check(field!=null,"inline composer exists");field.setText(prompt);View send=described(activity.getWindow().getDecorView(),c.getString(c.getResources().getIdentifier("assistant_send_1214d","string",c.getPackageName())));check(send!=null,"shared send control exists");sent=SystemClock.elapsedRealtime();send.performClick();check(text(activity.getWindow().getDecorView()).contains(prompt),"user bubble appears during send click");check(field.getText().length()==0,"draft cleared on accepted send");});
  screenshot("history-immediate");long firstPartial=-1,finished=-1,end=sent+150000;String previous="";int partialUpdates=0;
  while(SystemClock.elapsedRealtime()<end){JSONObject state=AssistantConversation.state(c);String status=state.optString("status"),partial=state.optString("partial_reply");
   check(thread.equals(state.optString("thread_id")),"same native conversation");
   if(status.equals("running")&&!partial.isBlank()&&!partial.equals(previous)){previous=partial;partialUpdates++;Thread.sleep(120);final String expected=partial.substring(0,Math.min(30,partial.length()));final boolean[] visible={false};runOnMainSync(()->visible[0]=text(activity.getWindow().getDecorView()).contains(expected));if(visible[0]&&!sawPartial){firstPartial=SystemClock.elapsedRealtime()-sent;sawPartial=true;screenshot("history-drag-before");runOnMainSync(()->{try{java.lang.reflect.Field field=os.aios.workspace.WorkspaceActivity.class.getDeclaredField("scroll");field.setAccessible(true);viewport=(ScrollView)field.get(activity);long now=SystemClock.uptimeMillis();viewport.dispatchTouchEvent(MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,100,300,0));viewport.dispatchTouchEvent(MotionEvent.obtain(now,now+30,MotionEvent.ACTION_MOVE,100,550,0));viewport.dispatchTouchEvent(MotionEvent.obtain(now,now+60,MotionEvent.ACTION_CANCEL,100,550,0));viewport.scrollTo(0,0);initialY=viewport.getScrollY();java.lang.reflect.Field f=os.aios.workspace.WorkspaceActivity.class.getDeclaredField("chatFollow");f.setAccessible(true);initialFollow=((os.aios.core.ChatScrollFollow)f.get(activity)).following();}catch(Exception e){throw new RuntimeException(e);}});}}
   if(!status.equals("running")&&!status.equals("queued")){finished=SystemClock.elapsedRealtime()-sent;check(state.optString("reply").contains("STREAM_END_45"),"real model reply completed");break;}Thread.sleep(200);
  }
  check(sawPartial,"partial reply rendered before completion");check(partialUpdates>1,"multiple stream updates");check(finished>firstPartial,"partial precedes final reply");Thread.sleep(1200);runOnMainSync(()->{try{java.lang.reflect.Field field=os.aios.workspace.WorkspaceActivity.class.getDeclaredField("scroll");field.setAccessible(true);ScrollView latest=(ScrollView)field.get(activity);finalY=latest.getScrollY();java.lang.reflect.Field f=os.aios.workspace.WorkspaceActivity.class.getDeclaredField("chatFollow");f.setAccessible(true);finalFollow=((os.aios.core.ChatScrollFollow)f.get(activity)).following();}catch(Exception e){throw new RuntimeException(e);}});screenshot("history-drag-final");out.putString("scroll",initialY+"/"+initialFollow+" -> "+finalY+"/"+finalFollow);check(finalY<100,"user reading older messages remains at top after streamed updates");out.putString("reply",AssistantConversation.state(c).optString("reply"));
  out.putLong("first_visible_partial_ms",firstPartial);out.putLong("completion_ms",finished);out.putInt("partial_updates",partialUpdates);out.putString("result","PASS "+checks+" checks");
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));}finally{finish(out.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,out);}}
}
